function drawBox(cx,cy,w,vals,group){
  var g=group.group();
  var x=cx-w/2, y=cy-boxH/2;
  g.rect(w,boxH).attr({x:x,y:y,fill:boxFill,stroke:boxStroke,'stroke-width':1.2}).move(x,y);
  var n=vals.length;
  for(var i=0;i<n;i++){
    var tx=x+(i+0.5)*(w/n);
    var t=g.text(String(vals[i])).attr({'font-size':fontSize,'text-anchor':'middle','dominant-baseline':'central',fill:'#111','font-family':'serif'});
    t.move(tx,cy);
  }
  return g;
}

function drawArrow(x1,y1,x2,y2,group){
  var g=group.group();
  var line=g.line(x1,y1,x2,y2).attr({stroke:arrowColor,'stroke-width':5,'stroke-linecap':'round'});
  // arrowhead
  var angle=Math.atan2(y2-y1,x2-x1);
  var ahl=12, ahw=6;
  var ax=x2, ay=y2;
  var p1x=ax-ahl*Math.cos(angle)+ahw*Math.sin(angle);
  var p1y=ay-ahl*Math.sin(angle)-ahw*Math.cos(angle);
  var p2x=ax-ahl*Math.cos(angle)-ahw*Math.sin(angle);
  var p2y=ay-ahl*Math.sin(angle)+ahw*Math.cos(angle);
  g.polygon([[ax,ay],[p1x,p1y],[p2x,p2y]]).attr({fill:arrowColor});
  return g;
}

