// Row2→row3
for(var i=0;i<2;i++){
  var c1=row2Centers[i*2], c2=row2Centers[i*2+1], pc=row3Centers[i];
  var a1=drawArrow(c1,row2Y-boxH/2-4,pc-20,row3Y+boxH/2+4,latticeGroup);
  var a2=drawArrow(c2,row2Y-boxH/2-4,pc+20,row3Y+boxH/2+4,latticeGroup);
  arrowEls.push([a1,a2]);
}
// Row3→top
var a1=drawArrow(row3Centers[0],row3Y-boxH/2-4,topCenter-30,topY+boxH/2+4,latticeGroup);
var a2=drawArrow(row3Centers[1],row3Y-boxH/2-4,topCenter+30,topY+boxH/2+4,latticeGroup);
arrowEls.push([a1,a2]);

// Merge labels
var mergePositions=[
  [(bottomCenters[0]+bottomCenters[1])/2, (bottomY+row2Y)/2+10],
  [(bottomCenters[2]+bottomCenters[3])/2, (bottomY+row2Y)/2+10],
  [(bottomCenters[4]+bottomCenters[5])/2, (bottomY+row2Y)/2+10],
  [(bottomCenters[6]+bottomCenters[7])/2, (bottomY+row2Y)/2+10],
  [(row2Centers[0]+row2Centers[1])/2, (row2Y+row3Y)/2+10],
  [(row2Centers[2]+row2Centers[3])/2, (row2Y+row3Y)/2+10],
  [(row3Centers[0]+row3Centers[1])/2, (row3Y+topY)/2+10]
];
for(var i=0;i<7;i++){
  var t=latticeGroup.text('merge').attr({'font-size':14,'text-anchor':'middle','font-style':'italic',fill:'#333','font-family':'serif'});
  t.move(mergePositions[i][0],mergePositions[i][1]);
  mergeLabels.push(t);
}

// Labels
var topLabel=latticeGroup.text('sorted sequence').attr({'font-size':16,'text-anchor':'middle',fill:'#111','font-family':'serif'});
topLabel.move(topCenter,topY-boxH/2-18);
var botLabel=latticeGroup.text('initial sequence').attr({'font-size':16,'text-anchor':'middle',fill:'#111','font-family':'serif'});
botLabel.move(380,bottomY+boxH/2+20);

// ─── Stability tags ─────────────────────────────────────────────────────
var stabGroup=draw.group();
var stabTags=[];
function drawStabilityTags(){
  stabGroup.clear();
  stabTags=[];
  if(!stabilityOn) return;
  // Tag 2^L at bottom index 1, 2^R at bottom index 6
  var tagL=stabGroup.text('2').attr({'font-size':12,fill:'#1565c0','font-weight':'bold','font-family':'serif'});
  var supL=stabGroup.text('L').attr({'font-size':8,fill:'#1565c0','font-family':'serif'});
  var lx=bottomCenters[1]+bw1/2+2, ly=bottomY-8;
  tagL.move(lx,ly); supL.move(lx+8,ly-4);
  stabTags.push(tagL,supL);
  var tagR=stabGroup.text('2').attr({'font-size':12,fill:'#e65100','font-weight':'bold','font-family':'serif'});
  var supR=stabGroup.text('R').attr({'font-size':8,fill:'#e65100','font-family':'serif'});
  var rx=bottomCenters[6]+bw1/2+2, ry=bottomY-8;
  tagR.move(rx,ry); supR.move(rx+8,ry-4);
  stabTags.push(tagR,supR);
  // Also tag in top row: first 2 is L (index 1), second 2 is R (index 2)
  var tw=bw4/8;
  var tlx=topCenter-bw4/2+1.5*tw+tw/2, tly=topY-boxH/2-6;
  var t2=stabGroup.text('2').attr({'font-size':10,fill:'#1565c0','font-weight':'bold'});
  var ts2=stabGroup.text('L').attr({'font-size':7,fill:'#1565c0'});
  t2.move(tlx,tly); ts2.move(tlx+7,tly-3);
  stabTags.push(t2,ts2);
  var trx=topCenter-bw4/2+2.5*tw+tw/2, trly=topY-boxH/2-6;
  var t3=stabGroup.text('2').attr({'font-size':10,fill:'#e65100','font-weight':'bold'});
  var ts3=stabGroup.text('R').attr({'font-size':7,fill:'#e65100'});
  t3.move(trx,trly); ts3.move(trx+7,trly-3);
  stabTags.push(t3,ts3);
}

// ─── Merge step highlighting ────────────────────────────────────────────
var currentStep='leaves';
var allBoxes=[];
for(var i=0;i<8;i++) allBoxes.push(boxEls.bottom[i]);
for(var i=0;i<4;i++) allBoxes.push(boxEls.row2[i]);
for(var i=0;i<2;i++) allBoxes.push(boxEls.row3[i]);
allBoxes.push(boxEls.top[0]);

function update_mergeStep(val){
  currentStep=val;
  // Reset all
  for(var i=0;i<allBoxes.length;i++){
    allBoxes[i].opacity(1);
    allBoxes[i].find('rect').attr({fill:boxFill,stroke:boxStroke});
  }
  for(var i=0;i<arrowEls.length;i++){
    arrowEls[i][0].opacity(1); arrowEls[i][1].opacity(1);
    arrowEls[i][0].find('line').attr({stroke:arrowColor});
    arrowEls[i][1].find('line').attr({stroke:arrowColor});
    arrowEls[i][0].find('polygon').attr({fill:arrowColor});
    arrowEls[i][1].find('polygon').attr({fill:arrowColor});
  }
  for(var i=0;i<mergeLabels.length;i++) mergeLabels[i].opacity(1);

  if(val==='leaves') return;

  // Dim everything first
  for(var i=0;i<allBoxes.length;i++) allBoxes[i].opacity(dimOpacity);
  for(var i=0;i<arrowEls.length;i++){arrowEls[i][0].opacity(dimOpacity);arrowEls[i][1].opacity(dimOpacity);}
  for(var i=0;i<mergeLabels.length;i++) mergeLabels[i].opacity(dimOpacity);

  var mi=parseInt(val.charAt(1))-1; // 0-6
  // Highlight the relevant boxes and arrows
  var childBoxes=[], parentBox=null, arrowIdx=mi;
  if(mi<4){
    childBoxes=[boxEls.bottom[mi*2],boxEls.bottom[mi*2+1]];
    parentBox=boxEls.row2[mi];
  } else if(mi<6){
    var ri=mi-4;
    childBoxes=[boxEls.row2[ri*2],boxEls.row2[ri*2+1]];
    parentBox=boxEls.row3[ri];
  } else {
    childBoxes=[boxEls.row3[0],boxEls.row3[1]];
    parentBox=boxEls.top[0];
  }
  for(var i=0;i<childBoxes.length;i++){
    childBoxes[i].opacity(1);
    childBoxes[i].find('rect').attr({fill:highlightFill,stroke:highlightStroke});
  }
  parentBox.opacity(1);
  parentBox.find('rect').attr({fill:highlightFill,stroke:highlightStroke});
  arrowEls[arrowIdx][0].opacity(1); arrowEls[arrowIdx][1].opacity(1);
  arrowEls[arrowIdx][0].find('line').attr({stroke:highlightStroke});
  arrowEls[arrowIdx][1].find('line').attr({stroke:highlightStroke});
  arrowEls[arrowIdx][0].find('polygon').attr({fill:highlightStroke});
  arrowEls[arrowIdx][1].find('polygon').attr({fill:highlightStroke});
  mergeLabels[arrowIdx].opacity(1);
}

function toggle_stabilityTrace(on){
  stabilityOn=on;
  drawStabilityTags();
}

// ─── Code editor trace visualization ────────────────────────────────────
var traceGroup=draw.group();
var traceY=640; // y position for trace area

function drawTraceFrame(frame){
  traceGroup.clear();
  if(!frame) return;
  var st=frame.state;
  var left=st.left, right=st.right, output=st.output;
  var lp=st.leftPtr, rp=st.rightPtr;
  var origins=st.outputOrigins||[];
  var bw=32, bh=28, gap=2;
  var startX=40;
  var y1=traceY, y2=traceY+50;

  // Label
  traceGroup.text('Merge trace:').attr({'font-size':11,fill:'#555','font-family':'sans-serif'}).move(startX,y1-18);

  // Left run
  traceGroup.text('L:').attr({'font-size':11,fill:'#1565c0','font-weight':'bold'}).move(startX,y1+bh/2);
  for(var i=0;i<left.length;i++){
    var x=startX+24+i*(bw+gap);
    var consumed=i<lp;
    var isFront=i===lp;
    var fill=consumed?'#ccc':(isFront?'#bbdefb':boxFill);
    var stroke=isFront?'#1565c0':boxStroke;
    traceGroup.rect(bw,bh).attr({x:x,y:y1,fill:fill,stroke:stroke,'stroke-width':isFront?2:1}).move(x,y1);
    var valText=String(left[i]);
    if(stabilityOn&&left[i]===2){
      var tEl=traceGroup.text(valText).attr({'font-size':12,'text-anchor':'middle',fill:consumed?'#999':'#1565c0','font-weight':'bold'});
      tEl.move(x+bw/2,y1+bh/2);
      var sEl=traceGroup.text('L').attr({'font-size':7,fill:'#1565c0'});
      sEl.move(x+bw/2+6,y1+4);
    } else {
      var tEl=traceGroup.text(valText).attr({'font-size':12,'text-anchor':'middle',fill:consumed?'#999':'#111'});
      tEl.move(x+bw/2,y1+bh/2);
    }
    if(isFront){
      traceGroup.polygon([[x+bw/2-5,y1-6],[x+bw/2+5,y1-6],[x+bw/2,y1-1]]).attr({fill:'#1565c0'});
    }
  }

  // Right run
  var rStart=startX+24+left.length*(bw+gap)+30;
  traceGroup.text('R:').attr({'font-size':11,fill:'#e65100','font-weight':'bold'}).move(rStart-20,y1+bh/2);
  for(var i=0;i<right.length;i++){
    var x=rStart+i*(bw+gap);
    var consumed=i<rp;
    var isFront=i===rp;
    var fill=consumed?'#ccc':(isFront?'#ffe0b2':boxFill);
    var stroke=isFront?'#e65100':boxStroke;
    traceGroup.rect(bw,bh).attr({x:x,y:y1,fill:fill,stroke:stroke,'stroke-width':isFront?2:1}).move(x,y1);
    var valText=String(right[i]);
    if(stabilityOn&&right[i]===2){
      var tEl=traceGroup.text(valText).attr({'font-size':12,'text-anchor':'middle',fill:consumed?'#999':'#e65100','font-weight':'bold'});
      tEl.move(x+bw/2,y1+bh/2);
      var sEl=traceGroup.text('R').attr({'font-size':7,fill:'#e65100'});
      sEl.move(x+bw/2+6,y1+4);
    } else {
      var tEl=traceGroup.text(valText).attr({'font-size':12,'text-anchor':'middle',fill:consumed?'#999':'#111'});
      tEl.move(x+bw/2,y1+bh/2);
    }
    if(isFront){
      traceGroup.polygon([[x+bw/2-5,y1-6],[x+bw/2+5,y1-6],[x+bw/2,y1-1]]).attr({fill:'#e65100'});
    }
  }

  // Output
  traceGroup.text('Out:').attr({'font-size':11,fill:'#333','font-weight':'bold'}).move(startX,y2+bh/2);
  for(var i=0;i<output.length;i++){
    var x=startX+34+i*(bw+gap);
    var orig=origins[i]||'';
    var fill='#e8f5e9';
    var stroke='#388e3c';
    if(stabilityOn&&output[i]===2){
      fill=orig==='L'?'#e3f2fd':'#fff3e0';
      stroke=orig==='L'?'#1565c0':'#e65100';
    }
    traceGroup.rect(bw,bh).attr({x:x,y:y2,fill:fill,stroke:stroke,'stroke-width':1}).move(x,y2);
    var valText=String(output[i]);
    var tEl=traceGroup.text(valText).attr({'font-size':12,'text-anchor':'middle',fill:stabilityOn&&output[i]===2?(orig==='L'?'#1565c0':'#e65100'):'#111','font-weight':stabilityOn&&output[i]===2?'bold':'normal'});
    tEl.move(x+bw/2,y2+bh/2);
    if(stabilityOn&&output[i]===2){
      var sEl=traceGroup.text(orig).attr({'font-size':7,fill:orig==='L'?'#1565c0':'#e65100'});
      sEl.move(x+bw/2+6,y2+4);
    }
  }
}

// ─── Code editor logic ──────────────────────────────────────────────────
var sampleCode='function merge(left, right) {\n  while (!left_done() && !right_done()) {\n    if (less_eq_left()) { take_left(); }\n    else { take_right(); }\n  }\n  if (left_done()) { finish("right"); }\n  else { finish("left"); }\n}';
var buggyCode='function merge(left, right) {\n  while (!left_done() && !right_done()) {\n    // BUG: strict < breaks stability\n    if (left_front() < right_front()) { take_left(); }\n    else { take_right(); }\n  }\n  if (left_done()) { finish("right"); }\n  else { finish("left"); }\n}';
var starterCode='function merge(left, right) {\n  // Use: less_eq_left(), take_left(), take_right(),\n  //        left_done(), right_done(), finish("left"|"right")\n}';

var currentTab='sample';
var frames=[];
var frameIdx=0;
var playing=false;
var playTimer=null;
var runStatus='not-run';

var codeEl=document.getElementById('mergeCodeCode');
codeEl.value=sampleCode;

function switchTab(tab){
  currentTab=tab;
  document.getElementById('tabSample').className=tab==='sample'?'active':'';
  document.getElementById('tabBuggy').className=tab==='buggy'?'active':'';
  document.getElementById('tabStarter').className=tab==='starter'?'active':'';
  codeEl.value=tab==='sample'?sampleCode:tab==='buggy'?buggyCode:starterCode;
}

function parseInput(str){
  var parts=str.split('|');
  if(parts.length!==2) return null;
  var left=parts[0].trim().split(',').map(Number);
  var right=parts[1].trim().split(',').map(Number);
  if(left.some(isNaN)||right.some(isNaN)) return null;
  return {left:left,right:right};
}

function runCode(){
  var input=parseInput(document.getElementById('mergeCodeInputField').value);
  if(!input){
    document.getElementById('runStatus').textContent='⚠ Invalid input format';
    document.getElementById('runStatus').style.color='#c00';
    return;
  }
  stopPlayback();
  frames=[];frameIdx=0;
  runStatus='running';
  document.getElementById('runStatus').textContent='⏳ Running...';
  document.getElementById('runStatus').style.color='#555';
  document.getElementById('runBtn').disabled=true;

  var code=codeEl.value;
  var workerSrc=buildWorkerSrc();
  var blob=new Blob([workerSrc],{type:'application/javascript'});
  var url=URL.createObjectURL(blob);
  var worker=new Worker(url);
  var startTime=Date.now();

  worker.onmessage=function(e){
    URL.revokeObjectURL(url);
    worker.terminate();
    document.getElementById('runBtn').disabled=false;
    var d=e.data;
    frames=d.frames||[];
    frameIdx=0;
    if(d.type==='error'){
      runStatus='error';
      document.getElementById('runStatus').textContent='✗ Error: '+d.error;
      document.getElementById('runStatus').style.color='#c00';
    } else if(d.type==='timeout'){
      runStatus='error';
      document.getElementById('runStatus').textContent='⏱ Timeout';
      document.getElementById('runStatus').style.color='#c00';
    } else {
      if(d.sorted&&d.stable){
        runStatus='correct';
        document.getElementById('runStatus').textContent='✓ Correct & stable';
        document.getElementById('runStatus').style.color='#2e7d32';
      } else if(d.sorted&&!d.stable){
        runStatus='wrong';
        document.getElementById('runStatus').textContent='✗ Sorted but NOT stable (2ᴿ before 2ᴸ)';
        document.getElementById('runStatus').style.color='#e65100';
      } else {
        runStatus='wrong';
        document.getElementById('runStatus').textContent='✗ Output not sorted';
        document.getElementById('runStatus').style.color='#c00';
      }
    }
    document.getElementById('playbackControls').style.display=frames.length?'block':'none';
    showFrame(0);
  };
  worker.onerror=function(e){
    URL.revokeObjectURL(url);
    worker.terminate();
    document.getElementById('runBtn').disabled=false;
    runStatus='error';
    document.getElementById('runStatus').textContent='✗ '+e.message;
    document.getElementById('runStatus').style.color='#c00';
  };
  worker.postMessage({code:code,left:input.left,right:input.right,stability:stabilityOn});
  // Timeout
  setTimeout(function(){
    try{worker.terminate();}catch(e){}
    URL.revokeObjectURL(url);
    if(runStatus==='running'){
      document.getElementById('runBtn').disabled=false;
      runStatus='error';
      document.getElementById('runStatus').textContent='⏱ Timeout (2s)';
      document.getElementById('runStatus').style.color='#c00';
    }
  },2000);
}

function buildWorkerSrc(){
  return `self.onmessage=function(e){
var d=e.data,code=d.code,left=d.left.slice(),right=d.right.slice();
var output=[],leftPtr=0,rightPtr=0,frames=[],opCount=0,maxOps=2000,maxFrames=500;
var outputOrigins=[];
var start=Date.now();
function chk(){opCount++;if(opCount>maxOps)throw new Error('Op limit');if(Date.now()-start>1800)throw new Error('Timeout');if(frames.length>=maxFrames)throw new Error('Frame limit');}
function rec(kind,idx,msg){frames.push({kind:kind,state:{left:left.slice(),right:right.slice(),output:output.slice(),leftPtr:leftPtr,rightPtr:rightPtr,outputOrigins:outputOrigins.slice()},indices:idx||[],message:msg});}
function less_eq_left(){chk();var r=left[leftPtr]<=right[rightPtr];rec('less_eq_left',[leftPtr,rightPtr],'left['+leftPtr+']='+left[leftPtr]+' <= right['+rightPtr+']='+right[rightPtr]+' → '+r);return r;}
function take_left(){chk();var v=left[leftPtr];output.push(v);outputOrigins.push('L');leftPtr++;rec('take_left',[leftPtr-1],'take L='+v+' → out=['+output.join(',')+']');return v;}
function take_right(){chk();var v=right[rightPtr];output.push(v);outputOrigins.push('R');rightPtr++;rec('take_right',[rightPtr-1],'take R='+v+' → out=['+output.join(',')+']');return v;}
function left_done(){chk();var r=leftPtr>=left.length;rec('left_done',[],'left_done() → '+r);return r;}
function right_done(){chk();var r=rightPtr>=right.length;rec('right_done',[],'right_done() → '+r);return r;}
function finish(side){chk();var idx=[];if(side==='left'){while(leftPtr<left.length){output.push(left[leftPtr]);outputOrigins.push('L');idx.push(leftPtr);leftPtr++;}}else{while(rightPtr<right.length){output.push(right[rightPtr]);outputOrigins.push('R');idx.push(rightPtr);rightPtr++;}}rec('finish',idx,'finish("'+side+'") → out=['+output.join(',')+']');}
function left_front(){chk();return left[leftPtr];}
function right_front(){chk();return right[rightPtr];}
rec('init',[],'left=['+left.join(',')+'] right=['+right.join(',')+']');
try{
var fn=new Function('less_eq_left','take_left','take_right','left_done','right_done','finish','left_front','right_front','left','right',code+'\\nmerge(left,right);');
fn(less_eq_left,take_left,take_right,left_done,right_done,finish,left_front,right_front,left,right);
rec('done',[],'Done: out=['+output.join(',')+']');
var sorted=true;for(var i=1;i<output.length;i++){if(output[i]<output[i-1]){sorted=false;break;}}
var stable=true;
if(d.stability){var fL=false;for(var i=0;i<output.length;i++){if(output[i]===2&&outputOrigins[i]==='R'&&!fL){stable=false;break;}if(output[i]===2&&outputOrigins[i]==='L')fL=true;}}
self.postMessage({type:'success',frames:frames,sorted:sorted,stable:stable});
}catch(err){rec('error',[],'Error: '+err.message);self.postMessage({type:'error',frames:frames,error:err.message});}
};`;
}

function showFrame(idx){
  if(!frames.length) return;
  frameIdx=Math.max(0,Math.min(idx,frames.length-1));
  drawTraceFrame(frames[frameIdx]);
  document.getElementById('frameCounter').textContent=(frameIdx+1)+'/'+frames.length;
  document.getElementById('frameCaption').textContent=frames[frameIdx].message||'';
}

function playFirst(){stopPlayback();showFrame(0);}
function playPrev(){stopPlayback();showFrame(frameIdx-1);}
function playNext(){stopPlayback();showFrame(frameIdx+1);}
function playToggle(){
  if(playing){stopPlayback();}
  else{
    playing=true;
    document.getElementById('playPauseBtn').textContent='⏸';
    tick();
  }
}
function tick(){
  if(!playing) return;
  if(frameIdx>=frames.length-1){stopPlayback();return;}
  showFrame(frameIdx+1);
  var spd=parseInt(document.getElementById('speedInput').value)||2;
  playTimer=setTimeout(tick,1200/spd);
}
function stopPlayback(){
  playing=false;
  clearTimeout(playTimer);
  document.getElementById('playPauseBtn').textContent='▶';
}

// ─── Demo steps ─────────────────────────────────────────────────────────
var demoSteps=[
  {title:'The merge lattice',narration:'Read bottom-up: eight singletons merge pairwise into sorted 2-runs, those into 4-runs, and finally into the one sorted 8-run. Each rank doubles the run length while halving the number of boxes.',state:{mergeStep:'leaves',stabilityTrace:false}},
  {title:'Step the merge calls',narration:'Advance the merge-call stepper in post-order. Watch the highlighted child pair, its merge arrow, and the destination box: a parent run appears only after both children are already sorted.',state:{mergeStep:'M5',stabilityTrace:false}},
  {title:'Run the merge routine',narration:'On the headline merge (2 4 5 7 | 1 2 3 6), step the code frame by frame: each step compares the two fronts and appends the smaller, then drains whichever side survives.',state:{mergeStep:'M7',stabilityTrace:false}},
  {title:'See stability',narration:'Turn the stability trace on and rerun. The two equal 2s are tagged by origin; a <= comparison keeps 2ᴸ before 2ᴿ, while switching to the buggy strict-< version lets 2ᴿ jump ahead.',state:{mergeStep:'M7',stabilityTrace:true}}
];
var stepIdx=0;

function applyStep(idx){
  stepIdx=idx;
  var s=demoSteps[idx];
  document.getElementById('demoNarration').textContent=s.narration;
  document.getElementById('stepLabel').textContent=(idx+1)+'/'+demoSteps.length;
  document.getElementById('mergeStepInput').value=s.state.mergeStep;
  update_mergeStep(s.state.mergeStep);
  document.getElementById('stabilityTraceInput').checked=s.state.stabilityTrace;
  toggle_stabilityTrace(s.state.stabilityTrace);
}
function prevStep(){if(stepIdx>0)applyStep(stepIdx-1);}
function nextStep(){if(stepIdx<demoSteps.length-1)applyStep(stepIdx+1);}

// ─── Init ───────────────────────────────────────────────────────────────
applyStep(0);
window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Merge sort builds a sorted sequence by repeatedly merging adjacent already-sorted runs, doubling run length at each level, and the inner merge routine must compare the two fronts and take the smaller (using <= on ties) to stay correct and stable.
KEY INSIGHT (what students should walk away understanding): Merge sort's correctness comes from merging already-sorted runs, and its stability comes from a single detail in the inner loop: on a tie, take from the left run (use <=), which keeps equal keys in their original relative order.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Merge sort builds a sorted sequence by repeatedly merging adjacent already-sorted runs, doubling run length at each level, and the inner merge routine must compare the two fronts and take the smaller (using <= on ties) to stay correct and stable.",
  "figureType": "diagram",
  "elements": [
    "bottom label 'initial sequence'",
    "rank of eight single-element gray squares reading 5, 2, 4, 7, 1, 3, 2, 6 left to right",
    "four two-element gray boxes reading 2 5, 4 7, 1 3, 2 6",
    "two four-element gray boxes reading 2 4 5 7 and 1 2 3 6",
    "top wide gray box reading 1 2 2 3 4 5 6 7 with label 'sorted sequence' above it",
    "thick gray upward arrows linking each pair of child boxes to its parent merged box",
    "the caption 'merge' beside each converging arrow pair (seven merge sites total)",
    "box widths scaling with run length so runs visibly widen and halve in count per rank",
