var stabilityOn=false;

// ─── Layout constants ───────────────────────────────────────────────────
var boxH=34, fontSize=15;
var topY=120, row3Y=250, row2Y=380, bottomY=510;
var arrowColor='#888', boxFill='#e8e8e8', boxStroke='#333';
