for(var i=0;i<2;i++) boxEls.row3.push(drawBox(row3Centers[i],row3Y,bw3,row3[i],latticeGroup));
boxEls.top.push(drawBox(topCenter,topY,bw4,topRow,latticeGroup));

for(var i=0;i<4;i++){
  var c1=bottomCenters[i*2], c2=bottomCenters[i*2+1], pc=row2Centers[i];
  arrowEls.push([drawArrow(c1,bottomY-boxH/2-4,pc-14,row2Y+boxH/2+4,latticeGroup),
                 drawArrow(c2,bottomY-boxH/2-4,pc+14,row2Y+boxH/2+4,latticeGroup)]);
}
for(var i=0;i<2;i++){
  var c1=row2Centers[i*2], c2=row2Centers[i*2+1], pc=row3Centers[i];
