var mergeYs=[(bottomY+row2Y)/2,(row2Y+row3Y)/2,(row3Y+topY)/2];
var mergePositions=[
  [row2Centers[0],mergeYs[0]],[row2Centers[1],mergeYs[0]],[row2Centers[2],mergeYs[0]],[row2Centers[3],mergeYs[0]],
