  [topCenter,mergeYs[2]]
];
for(var i=0;i<7;i++){
  mergeLabels.push(latticeGroup.text('merge').attr({'font-size':13,'text-anchor':'middle','font-style':'italic',fill:'#333','font-family':'serif'}).move(mergePositions[i][0],mergePositions[i][1]));
}

latticeGroup.text('sorted sequence').attr({'font-size':15,'text-anchor':'middle',fill:'#111','font-family':'serif'}).move(topCenter,topY-boxH/2-14);
latticeGroup.text('initial sequence').attr({'font-size':15,'text-anchor':'middle',fill:'#111','font-family':'serif'}).move(topCenter,bottomY+boxH/2+22);

// ─── Stability tags on lattice ──────────────────────────────────────────
var stabGroup=draw.group();
function drawStabilityTags(){
  stabGroup.clear();
  if(!stabilityOn) return;
  function tag(cx,cy,letter,color){
    stabGroup.text('2').attr({'font-size':11,fill:color,'font-weight':'bold','font-family':'serif'}).move(cx,cy);
    stabGroup.text(letter).attr({'font-size':8,fill:color,'font-family':'serif'}).move(cx+8,cy-4);
  }
  tag(bottomCenters[1]+bw1/2+1,bottomY-9,'L','#1565c0');
  tag(bottomCenters[6]+bw1/2+1,bottomY-9,'R','#e65100');
  var tw=bw4/8;
  tag(topCenter-bw4/2+1.5*tw+tw/2-4,topY-boxH/2-4,'L','#1565c0');
  tag(topCenter-bw4/2+2.5*tw+tw/2-4,topY-boxH/2-4,'R','#e65100');
}

// ─── Merge-step highlighting ────────────────────────────────────────────
var allBoxes=[];
for(var i=0;i<8;i++) allBoxes.push(boxEls.bottom[i]);
for(var i=0;i<4;i++) allBoxes.push(boxEls.row2[i]);
for(var i=0;i<2;i++) allBoxes.push(boxEls.row3[i]);
allBoxes.push(boxEls.top[0]);

function resetHighlight(){
  for(var i=0;i<allBoxes.length;i++){allBoxes[i].opacity(1);allBoxes[i].find('rect').attr({fill:boxFill,stroke:boxStroke});}
  for(var i=0;i<arrowEls.length;i++){
    arrowEls[i][0].opacity(1);arrowEls[i][1].opacity(1);
    arrowEls[i][0].find('line').attr({stroke:arrowColor});arrowEls[i][1].find('line').attr({stroke:arrowColor});
    arrowEls[i][0].find('polygon').attr({fill:arrowColor});arrowEls[i][1].find('polygon').attr({fill:arrowColor});
  }
