}
function update_mergeStep(val){
  resetHighlight();
  if(val==='leaves') return;
  for(var i=0;i<allBoxes.length;i++) allBoxes[i].opacity(dimOpacity);
  for(var i=0;i<arrowEls.length;i++){arrowEls[i][0].opacity(dimOpacity);arrowEls[i][1].opacity(dimOpacity);}
  for(var i=0;i<mergeLabels.length;i++) mergeLabels[i].opacity(dimOpacity);
  var mi=parseInt(val.charAt(1))-1;
  var childBoxes=[],parentBox=null;
  if(mi<4){childBoxes=[boxEls.bottom[mi*2],boxEls.bottom[mi*2+1]];parentBox=boxEls.row2[mi];}
  else if(mi<6){var ri=mi-4;childBoxes=[boxEls.row2[ri*2],boxEls.row2[ri*2+1]];parentBox=boxEls.row3[ri];}
  else {childBoxes=[boxEls.row3[0],boxEls.row3[1]];parentBox=boxEls.top[0];}
  for(var i=0;i<childBoxes.length;i++){childBoxes[i].opacity(1);childBoxes[i].find('rect').attr({fill:highlightFill,stroke:highlightStroke});}
  parentBox.opacity(1);parentBox.find('rect').attr({fill:highlightFill,stroke:highlightStroke});
  arrowEls[mi][0].opacity(1);arrowEls[mi][1].opacity(1);
  arrowEls[mi][0].find('line').attr({stroke:highlightStroke});arrowEls[mi][1].find('line').attr({stroke:highlightStroke});
  arrowEls[mi][0].find('polygon').attr({fill:highlightStroke});arrowEls[mi][1].find('polygon').attr({fill:highlightStroke});
