}

// ─── Merge-trace band (reserved vertical space, no collision) ───────────
var traceGroup=draw.group();
var traceY1=600, traceY2=652;
function drawTraceFrame(frame){
  traceGroup.clear();
  if(!frame) return;
  var st=frame.state, left=st.left, right=st.right, output=st.output;
  var lp=st.leftPtr, rp=st.rightPtr, origins=st.outputOrigins||[];
  var bw=30,bh=26,gap=2,startX=30;
  traceGroup.text('Merge trace:').attr({'font-size':11,fill:'#555','font-family':'sans-serif'}).move(startX,traceY1-16);
  function cell(x,y,val,fill,stroke,sw,origin){
    traceGroup.rect(bw,bh).attr({x:x,y:y,fill:fill,stroke:stroke,'stroke-width':sw});
    var col='#111';
    if(stabilityOn&&val===2&&origin) col=origin==='L'?'#1565c0':'#e65100';
    traceGroup.text(String(val)).attr({'font-size':12,'text-anchor':'middle','dominant-baseline':'central',fill:col,'font-weight':(stabilityOn&&val===2&&origin)?'bold':'normal','font-family':'serif'}).move(x+bw/2,y+bh/2);
    if(stabilityOn&&val===2&&origin) traceGroup.text(origin).attr({'font-size':7,fill:col}).move(x+bw/2+6,y+3);
  }
  traceGroup.text('L:').attr({'font-size':11,fill:'#1565c0','font-weight':'bold'}).move(startX,traceY1+bh/2);
  for(var i=0;i<left.length;i++){
    var x=startX+22+i*(bw+gap), consumed=i<lp, front=i===lp;
    cell(x,traceY1,left[i],consumed?'#d5d5d5':(front?'#bbdefb':boxFill),front?'#1565c0':boxStroke,front?2:1,'L');
    if(front) traceGroup.polygon([[x+bw/2-5,traceY1-6],[x+bw/2+5,traceY1-6],[x+bw/2,traceY1-1]]).attr({fill:'#1565c0'});
  }
  var rStart=startX+22+left.length*(bw+gap)+26;
  traceGroup.text('R:').attr({'font-size':11,fill:'#e65100','font-weight':'bold'}).move(rStart-20,traceY1+bh/2);
  for(var i=0;i<right.length;i++){
    var x=rStart+i*(bw+gap), consumed=i<rp, front=i===rp;
    cell(x,traceY1,right[i],consumed?'#d5d5d5':(front?'#ffe0b2':boxFill),front?'#e65100':boxStroke,front?2:1,'R');
    if(front) traceGroup.polygon([[x+bw/2-5,traceY1-6],[x+bw/2+5,traceY1-6],[x+bw/2,traceY1-1]]).attr({fill:'#e65100'});
  }
  traceGroup.text('Out:').attr({'font-size':11,fill:'#333','font-weight':'bold'}).move(startX,traceY2+bh/2);
  for(var i=0;i<output.length;i++){
    var x=startX+32+i*(bw+gap), orig=origins[i]||'';
    var fill='#e8f5e9',stroke='#388e3c';
    if(stabilityOn&&output[i]===2){fill=orig==='L'?'#e3f2fd':'#fff3e0';stroke=orig==='L'?'#1565c0':'#e65100';}
    cell(x,traceY2,output[i],fill,stroke,1,orig);
  }
}

// ─── Code editor ────────────────────────────────────────────────────────
var sampleCode='function merge(left, right) {\n  while (!left_done() && !right_done()) {\n    if (less_eq_left()) { take_left(); }\n    else { take_right(); }\n  }\n  if (left_done()) { finish("right"); }\n  else { finish("left"); }\n}';
var buggyCode='function merge(left, right) {\n  while (!left_done() && !right_done()) {\n    // BUG: strict < breaks stability — on a tie the right\n    // element wins, so 2R is emitted before 2L.\n    if (left_front() < right_front()) { take_left(); }\n    else { take_right(); }\n  }\n  if (left_done()) { finish("right"); }\n  else { finish("left"); }\n}';
var starterCode='function merge(left, right) {\n  // Use: less_eq_left(), take_left(), take_right(),\n  //        left_done(), right_done(), finish("left"|"right")\n}';

var currentTab='sample';
var frames=[], frameIdx=0, playing=false, playTimer=null, runStatus='not-run';
var codeEl=document.getElementById('mergeCodeCode');
codeEl.value=sampleCode;

function switchTab(tab){
  currentTab=tab;
  document.getElementById('tabSample').className=tab==='sample'?'active':'';
  document.getElementById('tabBuggy').className=tab==='buggy'?'active':'';
  document.getElementById('tabStarter').className=tab==='starter'?'active':'';
  codeEl.value=tab==='sample'?sampleCode:tab==='buggy'?buggyCode:starterCode;
}
function parseInput(str){
  var parts=str.split('|');
  if(parts.length!==2) return null;
  var left=parts[0].trim().split(',').map(Number);
  var right=parts[1].trim().split(',').map(Number);
  if(left.some(isNaN)||right.some(isNaN)||!left.length||!right.length) return null;
  return {left:left,right:right};
}
function buildWorkerSrc(){
  return 'self.onmessage=function(e){\n'+
  'var d=e.data,left=d.left.slice(),right=d.right.slice();\n'+
  'var output=[],leftPtr=0,rightPtr=0,frames=[],opCount=0,maxOps=2000,maxFrames=400,outputOrigins=[];\n'+
  'var start=Date.now();\n'+
  'function chk(){opCount++;if(opCount>maxOps)throw new Error("Op limit exceeded");if(Date.now()-start>1800)throw new Error("Timeout");if(frames.length>=maxFrames)throw new Error("Frame limit exceeded");}\n'+
  'function rec(kind,idx,msg){frames.push({kind:kind,state:{left:left.slice(),right:right.slice(),output:output.slice(),leftPtr:leftPtr,rightPtr:rightPtr,outputOrigins:outputOrigins.slice()},indices:idx||[],message:msg});}\n'+
  'function less_eq_left(){chk();var r=left[leftPtr]<=right[rightPtr];rec("less_eq_left",[leftPtr,rightPtr],"left["+leftPtr+"]="+left[leftPtr]+" <= right["+rightPtr+"]="+right[rightPtr]+" -> "+r);return r;}\n'+
  'function take_left(){chk();var v=left[leftPtr];output.push(v);outputOrigins.push("L");leftPtr++;rec("take_left",[leftPtr-1],"take L="+v+" -> out=["+output.join(",")+"]");return v;}\n'+
  'function take_right(){chk();var v=right[rightPtr];output.push(v);outputOrigins.push("R");rightPtr++;rec("take_right",[rightPtr-1],"take R="+v+" -> out=["+output.join(",")+"]");return v;}\n'+
  'function left_done(){chk();var r=leftPtr>=left.length;rec("left_done",[],"left_done() -> "+r);return r;}\n'+
  'function right_done(){chk();var r=rightPtr>=right.length;rec("right_done",[],"right_done() -> "+r);return r;}\n'+
  'function left_front(){chk();return left[leftPtr];}\n'+
  'function right_front(){chk();return right[rightPtr];}\n'+
  'function finish(side){chk();var idx=[];if(side==="left"){while(leftPtr<left.length){output.push(left[leftPtr]);outputOrigins.push("L");idx.push(leftPtr);leftPtr++;}}else{while(rightPtr<right.length){output.push(right[rightPtr]);outputOrigins.push("R");idx.push(rightPtr);rightPtr++;}}rec("finish",idx,"finish(\\""+side+"\\") -> out=["+output.join(",")+"]");}\n'+
  'rec("init",[],"left=["+left.join(",")+"]  right=["+right.join(",")+"]");\n'+
  'try{\n'+
  'var fn=new Function("less_eq_left","take_left","take_right","left_done","right_done","finish","left_front","right_front","left","right",d.code+"\\nmerge(left,right);");\n'+
  'fn(less_eq_left,take_left,take_right,left_done,right_done,finish,left_front,right_front,left,right);\n'+
  'rec("done",[],"Done: out=["+output.join(",")+"]");\n'+
  'var sorted=true;for(var i=1;i<output.length;i++){if(output[i]<output[i-1]){sorted=false;break;}}\n'+
  'var stable=true,fL=false;for(var i=0;i<output.length;i++){if(output[i]===2&&outputOrigins[i]==="R"&&!fL){stable=false;break;}if(output[i]===2&&outputOrigins[i]==="L")fL=true;}\n'+
  'self.postMessage({type:"success",frames:frames,sorted:sorted,stable:stable});\n'+
  '}catch(err){rec("error",[],"Error: "+err.message);self.postMessage({type:"error",frames:frames,error:err.message});}\n'+
  '};';
}
function runCode(){
  var input=parseInput(document.getElementById('mergeCodeInputField').value);
  if(!input){
    document.getElementById('runStatus').textContent='⚠ Invalid input — use "a,b,c | d,e,f"';
    document.getElementById('runStatus').style.color='#c00';
    return;
  }
  stopPlayback();
  frames=[];frameIdx=0;runStatus='running';
  document.getElementById('runStatus').textContent='⏳ Running...';
  document.getElementById('runStatus').style.color='#555';
  document.getElementById('runBtn').disabled=true;
  var blob=new Blob([buildWorkerSrc()],{type:'application/javascript'});
  var url=URL.createObjectURL(blob);
  var worker=new Worker(url);
  var done=false;
  function finishRun(d){
    if(done) return; done=true;
    URL.revokeObjectURL(url); try{worker.terminate();}catch(e){}
    document.getElementById('runBtn').disabled=false;
    frames=d.frames||[]; frameIdx=0;
    if(d.type==='error'){runStatus='error';document.getElementById('runStatus').textContent='✗ Error: '+d.error;document.getElementById('runStatus').style.color='#c00';}
    else if(d.sorted&&d.stable){runStatus='correct';document.getElementById('runStatus').textContent='✓ Correct & stable (2ᴸ before 2ᴿ)';document.getElementById('runStatus').style.color='#2e7d32';}
    else if(d.sorted&&!d.stable){runStatus='wrong';document.getElementById('runStatus').textContent='✗ Sorted but NOT stable (2ᴿ before 2ᴸ)';document.getElementById('runStatus').style.color='#e65100';}
    else {runStatus='wrong';document.getElementById('runStatus').textContent='✗ Output not sorted';document.getElementById('runStatus').style.color='#c00';}
    document.getElementById('playbackControls').style.display=frames.length?'block':'none';
    showFrame(0);
  }
  worker.onmessage=function(e){finishRun(e.data);};
  worker.onerror=function(e){finishRun({type:'error',error:e.message||'worker error',frames:[]});};
  worker.postMessage({code:codeEl.value,left:input.left,right:input.right});
  setTimeout(function(){if(!done) finishRun({type:'error',error:'Timeout (2s)',frames:[]});},2000);
}
function showFrame(idx){
  if(!frames.length) return;
